package com.akshat.ledgerwise.service;
import com.akshat.ledgerwise.model.*; import com.akshat.ledgerwise.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.Collectors;
@Service @Transactional
public class FinanceService {
 private final TransactionRepository transactions; private final BudgetRepository budgets;
 public FinanceService(TransactionRepository t,BudgetRepository b){transactions=t;budgets=b;}
 @Transactional(readOnly=true) public List<FinancialTransaction> allTransactions(){return transactions.findAllByOrderByTransactionDateDescIdDesc();}
 @Transactional(readOnly=true) public Optional<FinancialTransaction> findTransaction(Long id){return transactions.findById(id);}
 public FinancialTransaction saveTransaction(FinancialTransaction t){return transactions.save(t);} public void deleteTransaction(Long id){transactions.deleteById(id);}
 @Transactional(readOnly=true) public List<MonthlyBudget> budgetsFor(String month){return budgets.findByMonthKeyOrderByCategoryAsc(month);}
 public MonthlyBudget saveBudget(MonthlyBudget budget){budgets.findByMonthKeyOrderByCategoryAsc(budget.getMonthKey()).stream().filter(b->b.getCategory()==budget.getCategory()).findFirst().ifPresent(b->budget.setId(b.getId()));return budgets.save(budget);}
 @Transactional(readOnly=true) public Map<Category,BigDecimal> expenseTotals(String month){YearMonth ym=YearMonth.parse(month);return transactions.findByTypeAndTransactionDateBetween(TransactionType.EXPENSE,ym.atDay(1),ym.atEndOfMonth()).stream().collect(Collectors.groupingBy(FinancialTransaction::getCategory,()->new EnumMap<>(Category.class),Collectors.reducing(BigDecimal.ZERO,FinancialTransaction::getAmount,BigDecimal::add)));}
 @Transactional(readOnly=true) public BigDecimal total(TransactionType type,LocalDate start,LocalDate end){return transactions.findByTypeAndTransactionDateBetween(type,start,end).stream().map(FinancialTransaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}
 @Transactional(readOnly=true) public List<Map<String,Object>> cashFlowTrend(String month){
  YearMonth selected=YearMonth.parse(month); List<Map<String,Object>> rows=new ArrayList<>(); BigDecimal maximum=BigDecimal.ZERO;
  for(int offset=5;offset>=0;offset--){YearMonth ym=selected.minusMonths(offset);BigDecimal income=total(TransactionType.INCOME,ym.atDay(1),ym.atEndOfMonth());BigDecimal expense=total(TransactionType.EXPENSE,ym.atDay(1),ym.atEndOfMonth());maximum=maximum.max(income).max(expense);Map<String,Object> row=new LinkedHashMap<>();row.put("month",ym.toString());row.put("label",ym.getMonth().getDisplayName(java.time.format.TextStyle.SHORT,Locale.ENGLISH)+" "+ym.getYear());row.put("income",income);row.put("expense",expense);rows.add(row);}
  for(Map<String,Object> row:rows){BigDecimal income=(BigDecimal)row.get("income");BigDecimal expense=(BigDecimal)row.get("expense");int incomePercent=maximum.signum()==0?0:income.multiply(BigDecimal.valueOf(100)).divide(maximum,0,RoundingMode.HALF_UP).intValue();int expensePercent=maximum.signum()==0?0:expense.multiply(BigDecimal.valueOf(100)).divide(maximum,0,RoundingMode.HALF_UP).intValue();row.put("incomePercent",incomePercent);row.put("expensePercent",expensePercent);}
  return rows;
 }
 @Transactional(readOnly=true) public Map<String,Object> dashboard(String month){YearMonth ym=YearMonth.parse(month);BigDecimal income=total(TransactionType.INCOME,ym.atDay(1),ym.atEndOfMonth());BigDecimal expense=total(TransactionType.EXPENSE,ym.atDay(1),ym.atEndOfMonth());Map<Category,BigDecimal> totals=expenseTotals(month);List<Map<String,Object>> rows=new ArrayList<>();for(MonthlyBudget b:budgetsFor(month)){BigDecimal spent=totals.getOrDefault(b.getCategory(),BigDecimal.ZERO);Map<String,Object> row=new LinkedHashMap<>();row.put("category",b.getCategory());row.put("limit",b.getLimitAmount());row.put("spent",spent);row.put("remaining",b.getLimitAmount().subtract(spent));row.put("percent",spent.multiply(BigDecimal.valueOf(100)).divide(b.getLimitAmount(),0,RoundingMode.HALF_UP).min(BigDecimal.valueOf(100)).intValue());rows.add(row);}Map<String,Object> data=new HashMap<>();data.put("income",income);data.put("expense",expense);data.put("balance",income.subtract(expense));data.put("categoryTotals",totals);data.put("budgetRows",rows);data.put("recentTransactions",allTransactions().stream().limit(6).toList());data.put("month",month);return data;}
}